      shortInterest: { siPct: fr(st.shortPercentOfFloat, 2) + ' % du flottant', daysToCover: fr(st.shortRatio, 2) + ' jours', ctb: 'Non certifié', trend: nb(st.sharesShort) + ' actions vendues à découvert au dernier relevé bimensuel (instantané non daté du fournisseur) ; positions faibles, la baisse n’est pas une vente à découvert massive.', squeezeScore: 'Faible : peu de positions vendeuses à racheter', sourceRefs: [market('positions vendeuses')] },
